 if($book['title']===''||$book['author']===''||$book['category']===''||$quantity===false||$available===false||$available>$quantity||($book['publication_year']!==''&&$year===false)){$message='Enter a title, author, category, valid publication year, and copy counts.';}else{$newCover=uploadBookCover($_FILES['cover_image']??[],$message);if($message===''){if($newCover!==null)$book['cover_image']=$newCover;$isbn=$book['isbn']===''?null:$book['isbn'];$publisher=$book['publisher']===''?null:$book['publisher'];$description=$book['description']===''?null:$book['description'];$status=$available>0?'Available':'Borrowed';$stmt=$conn->prepare('UPDATE books SET title=?, isbn=?, author=?, publisher=?, publication_year=?, category=?, cover_image=?, quantity=?, available_copies=?, description=?, status=? WHERE id=?');$stmt->bind_param('ssssissiissi',$book['title'],$isbn,$book['author'],$publisher,$year,$book['category'],$book['cover_image'],$quantity,$available,$description,$status,$id);if($stmt->execute()){if($newCover!==null){deleteBookCover($current['cover_image']);}$_SESSION['flash']=['type'=>'success','message'=>'Book updated successfully.'];header('Location: books.php');exit();}if($newCover!==null){deleteBookCover($newCover);$book['cover_image']=$current['cover_image'];}$message='Unable to save the book. Please try again.';}}
