<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Book</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="styles.css"></head><body><?php include 'includes/nav.php'; ?><main class="container py-4"><section class="card shadow-sm mx-auto" style="max-width:850px"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Edit Book</h1><p class="text-muted mb-0">Update title details and available inventory.</p></div><a href="books.php" class="btn btn-outline-secondary">Back to Books</a></div><?php if($message): ?><div class="alert alert-danger"><?php echo htmlspecialchars($message); ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="id" value="<?php echo (int)$book['id']; ?>"><div class="col-md-8"><label class="form-label">Title *</label><input class="form-control" name="title" required value="<?php echo htmlspecialchars($book['title']); ?>"></div><div class="col-md-4"><label class="form-label">ISBN</label><input class="form-control" name="isbn" maxlength="20" value="<?php echo htmlspecialchars($book['isbn']??''); ?>"></div><div class="col-md-6"><label class="form-label">Author *</label><input class="form-control" name="author" required value="<?php echo htmlspecialchars($book['author']); ?>"></div><div class="col-md-6"><label class="form-label">Publisher</label><input class="form-control" name="publisher" value="<?php echo htmlspecialchars($book['publisher']??''); ?>"></div><div class="col-md-4"><label class="form-label">Publication Year</label><input class="form-control" name="publication_year" type="number" min="1000" max="<?php echo date('Y'); ?>" value="<?php echo htmlspecialchars((string)($book['publication_year']??'')); ?>"></div><div class="col-md-8"><label class="form-label">Category *</label><input class="form-control" name="category" list="category-list" required value="<?php echo htmlspecialchars($book['category']); ?>"><datalist id="category-list"><?php foreach($categories as $category): ?><option value="<?php echo htmlspecialchars($category['name']); ?>"><?php endforeach; ?></datalist></div><div class="col-md-6"><label class="form-label">Quantity *</label><input class="form-control" name="quantity" type="number" min="1" required value="<?php echo (int)$book['quantity']; ?>"></div><div class="col-md-6"><label class="form-label">Available Copies *</label><input class="form-control" name="available_copies" type="number" min="0" required value="<?php echo (int)$book['available_copies']; ?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4"><?php echo htmlspecialchars($book['description']??''); ?></textarea></div><div class="col-12"><label class="form-label">Replace Cover Image</label><input class="form-control" name="cover_image" type="file" accept="image/jpeg,image/png,image/gif,image/webp"><?php if(!empty($book['cover_image'])):?><img class="cover-preview mt-2" src="<?php echo htmlspecialchars($book['cover_image']); ?>" alt="Current cover"><?php endif;?></div><div class="col-12"><button class="btn btn-primary">Save Changes</button></div></form></div></section></main></body></html>
